(() => {
  const button=document.querySelector('#readBtn'); if(!button)return;
  const common={
    '命宮':'你面對世界、建立性格及人生主軸的宮位。','夫妻宮':'親密關係中的互動模式、期待及磨合課題，不等於直接預言婚姻。','官祿宮':'工作角色、責任、專業定位及被看見的方式。','財帛宮':'收入模式、資源運用及金錢安全感，不代表保證賺錢。','福德宮':'內在慾望、休息方式、精神壓力及享受能力。','田宅宮':'居住環境、家庭根基及長期資產觀念。','遷移宮':'離開熟悉環境後的表現、外部機會及移動。','疾厄宮':'身心壓力與生活習慣的提醒，不是醫療診斷。','父母宮':'長輩、權威、教育及早期支持系統。','兄弟宮':'手足、同儕及平輩合作模式。','子女宮':'創作、成果、照顧及你帶領後輩的方式。','僕役宮':'朋友、同事、客戶及社群互動。',
    '紫微':'核心領導、整合資源及承擔責任；失衡時容易控制過多。','天機':'思考、變通、策劃及資訊流動；失衡時容易反覆。','太陽':'公開性、付出、領導及男性／父系象徵；要留意過勞。','武曲':'執行、財務、紀律及結果導向；要留意太硬。','天同':'享受、和氣、福氣及調節壓力；要留意拖延。','廉貞':'界線、慾望、原則及關係張力；要留意灰色地帶。','天府':'資源管理、穩定、收藏及承擔；要留意保守。','太陰':'感受、照顧、資產及夜間思緒；要留意情緒內收。','貪狼':'人際、魅力、慾望、多才多藝；要留意分心。','巨門':'語言、質疑、研究及辯證；要留意誤會與口舌。','天相':'協調、公平、制度及中介角色；要留意過度顧全。','天梁':'保護、原則、長輩及解難；要留意說教。','七殺':'突破、決斷、競爭及高壓環境；要留意衝動。','破軍':'改革、拆舊立新及重新開始；要留意破壞後沒有重建。','左輔':'協助、團隊及有人幫手；要主動建立合作。','右弼':'人脈、支援及補位；要留意過度依賴。','文昌':'學習、文字、考試及表達；要靠整理輸出。','文曲':'審美、口才、感情表達及技巧；要留意情緒化。','天魁':'正面提攜、貴人及正式機會。','天鉞':'暗中協助、轉危為機及女性貴人。','祿存':'穩定資源、收入及保守累積；忌過度守成。','天馬':'移動、轉換、跨地域及忙碌；要管理節奏。','擎羊':'直接衝突、切割及壓力；宜用清晰界線。','陀羅':'延遲、糾纏及反覆；宜預留緩衝。','火星':'快速爆發、急促及即時反應；忌躁進。','鈴星':'暗地壓力、突發訊號及敏感度；要先留意預警。','地空':'理想落空、抽象化及重新定義價值。','地劫':'資源突然流失或改道；要設後備方案。','紅鸞':'情感吸引、喜事及關係啟動。','天喜':'社交喜氣、公開好消息及互動增加。','天刑':'規則、責任、法律或界線議題。','天姚':'魅力、曖昧及審美吸引；要講清楚界線。','解神':'解結、找方法及化解卡位。','天哭':'失落感、敏感及需要處理情緒。','天虛':'期待與現實落差；宜先核對事實。',
    '日主':'八字中代表本人核心五行及承受事情的方式；強弱要連同月令、根氣、透干及整體五行判斷。','年柱':'家族背景、早年環境及社會根源。','月柱':'成長環境、工作基礎及季節令氣。','日柱':'自己與親密關係核心；日干是日主，日支常作夫妻宮參考。','時柱':'後期發展、作品、子女及內在長期目標。','十神':'以日主和其他天干的生剋及陰陽關係分類，用來描述資源、輸出、責任、財務及同伴。','流年':'某一整年引入的主題，不是單獨決定吉凶。','流月':'流年中的月度節奏，用來安排先後次序。','流日':'短期觸發點，適合做提醒，不宜取代現實證據。',
    'Lagna':'出生時東方地平線上升星座，代表身體表現、行動方式及人生入口。','Moon sign':'月亮所在星座，反映情緒反應、習慣及安全感。','Bhava':'印度占星的生活領域宮位；本頁採 Whole-Sign，每一星座完整對應一宮。','Nakshatra':'月亮所在的二十七宿，用來細分心理模式及 Dasha 起點。','Pada':'每個 Nakshatra 的四分之一，提供更細的表達方式。','D9 Navamsa':'婚姻、內在成熟度及行星細部力量的分盤；不能脫離 D1 單獨判斷。','Maha Dasha':'較長期的行星主題。','Antar Dasha':'Maha Dasha 內的次周期，用來找近期焦點。','Transit':'現在天體相對出生盤的移動，用來找觸發時間。',
    '天盤':'奇門中按時空局移動的天干層，描述事情當下的動態。','地盤':'奇門局的固定基礎層，提供方位及環境底盤。','九星':'奇門中的九種功能象徵，如判斷思考、行動、阻力及資源。','八門':'奇門中的八種事件通道，如開門偏向機會，杜門偏向收斂。','八神':'奇門中的心理、氣勢及隱性因素層。','值符':'本局主導核心及最有影響力的星。','值使':'本局主導事件行動方式的門。','局數':'由節氣及時辰決定的盤局編號；不同流派起局法會有差異。','空亡':'該時間局中暫時落空、延遲或資訊不足的象徵，需配合其他層判斷。',
    '上卦':'卦象上半部，常用來觀察外在環境或對方一側。','下卦':'卦象下半部，常用來觀察自身基礎或內在一側。','動爻':'本次問題最容易發生變化的爻位。','本卦':'問題目前的基本結構。','變卦':'動爻改變後的發展方向，不是保證結果。','體用':'梅花易數中主體與作用／環境的分工，用生剋看互動。'
  };
  const explain=(method,text)=>{
    const terms=Object.keys(common).filter(k=>text.includes(k));
    const unique=[...new Set(terms)];
    let action='解讀原則：將術語視為傾向及問題拆解工具，不把單一星曜或卦象當成必然事件。';
    if(method==='紫微斗數')action+='先看命宮，再看與問題相關的夫妻、官祿、財帛或遷移宮，最後用三方四正及流限交叉核對。';
    if(method==='八字')action+='先確認日主及月令，再看五行生剋、十神分工及流年／流月／流日是否重複觸發同一主題。';
    if(method==='印度占星')action+='先看 Lagna 及 Moon，再看主宰目前 Dasha 的行星落宮，Transit 只作時間觸發，不單獨決定結果。';
    if(method==='奇門遁甲')action+='先定位值符、值使及用神所在宮，再比較門、星、神及空亡，將有利方向轉成實際溝通或行動安排。';
    if(['梅花易數','指一算','易經'].includes(method))action+='先讀本卦，再看動爻及變化；問時間就看節奏，問選擇就列出一個可驗證的取捨條件。';
    const glossary=unique.length?`\n\n術語逐項解釋：\n${unique.map(k=>`${k}：${common[k]}`).join('\n')}`:'';
    return `${text}${glossary}\n\n${action}\n\n實際回答方法：把你的問題拆成「已知資料、目前傾向、可控風險、下一個行動」四格；命理結果只負責提供假設，最後以現實證據覆核。`;
  };
  button.addEventListener('click',()=>setTimeout(()=>{const active=document.querySelector('.method.active')?.dataset.name,box=document.querySelector('#resultText');if(active&&box&&box.textContent)box.textContent=explain(active,box.textContent);},80));
})();
